105	export async function login(
106	  prev: any,
107	  formData: FormData,
108	): Promise<{ error?: string; needs2fa?: boolean }> {
109	  const parsed = credsSchema.safeParse({
110	    email: formData.get("email"),
111	    password: formData.get("password"),
112	  });
113	  if (!parsed.success) return { error: "Invalid email or password." };
114	
115	  // App-level throttle: 5 attempts / 15 min per email+IP.
116	  const hdrs = await headers();
117	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
118	  const rlId = `${parsed.data.email}:${ip}`;
119	  const rl = loginRateLimit(rlId);
120	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
121	
122	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
123	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
124	    return { error: "Invalid email or password." };
125	  }
126	  if (user.suspended) return { error: "This account is suspended." };
127	
128	  // Two-factor challenge, if enabled on the account.
129	  if (user.totpEnabled) {
130	    const code = String(formData.get("code") ?? "").trim();
131	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
132	    if (!(await verifyTotpForUser(user.id, code))) {
133	      return { error: "Invalid 2FA code.", needs2fa: true };
134	    }
135	  }
136	
137	  resetRateLimit(`login:${rlId}`);
138	  await audit(user.id, "user.login");
139	  await createSession(user.id);
140	  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
141	}
