150	const orderSchema = z.object({
151	  planId: z.string().min(1),
152	  osTemplateId: z.string().min(1),
153	  hostname: z
154	    .string()
155	    .min(3)
156	    .max(40)
157	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
158	});
