180	export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
181	  const user = await requireUser();
182	  const parsed = orderSchema.safeParse({
183	    planId: formData.get("planId"),
184	    osTemplateId: formData.get("osTemplateId"),
185	    hostname: formData.get("hostname"),
186	  });
187	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
188	
189	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
190	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
191	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
192	
193	  // Image requirements (control panels/apps need more resources)
194	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
195	    return {
196	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
197	    };
198	  }
199	
200	  const cap = await capacityCheck(plan.id);
201	  if (!cap.ok) return { error: cap.reason };
202	
203	  // Optional: node (location) selection, else auto-schedule
204	  const requestedNodeId = String(formData.get("nodeId") ?? "");
205	  let nodeId: string | null = null;
206	  if (requestedNodeId) {
207	    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
208	    if (!n) return { error: "Selected location is not available." };
209	    nodeId = n.id;
210	  } else {
211	    const n = await scheduleNode(plan.ramMB);
212	    nodeId = n?.id ?? null;
213	  }
214	
215	  // Add-ons (booleans)
216	  const addons = {
217	    malwareScanner: formData.get("addon_malware") === "1",
218	    dailyBackup: formData.get("addon_backup") === "1",
219	    docker: formData.get("addon_docker") === "1",
220	  };
221	
222	  // Optional SSH key added at deploy time
223	  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
224	  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);
225	
226	  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
227	  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
228	  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
229	  const ipCents = wantsDedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0;
230	  const chargeCents = vpsTermPriceCents(plan.priceCents, term.months) + ipCents;
231	
232	  const isAdmin = user.role === "ADMIN";
233	  const freeRequested = formData.get("free") === "1" && isAdmin;
234	
235	  if (!freeRequested && user.balanceCents < chargeCents) {
236	    return { error: "Insufficient balance. Top up your wallet first." };
237	  }
238	
239	  let server;
240	  try {
241	    server = await db.$transaction(async (tx) => {
242	    if (!freeRequested) {
243	      await debitWallet(tx, user.id, chargeCents);
244	      await tx.walletTransaction.create({
245	        data: {
246	          userId: user.id,
247	          amountCents: -chargeCents,
248	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}`,
249	        },
250	      });
251	    }
252	    if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
253	      const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
254	      if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
255	    }
256	    const s = await tx.server.create({
257	      data: {
258	        name: parsed.data.hostname,
259	        hostname: parsed.data.hostname,
260	        userId: user.id,
261	        planId: plan.id,
262	        osTemplateId: os.id,
263	        nodeId,
264	        addons,
265	        termMonths: term.months,
266	        wantsDedicatedIp,
267	        isFree: freeRequested,
268	        expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
269	      },
270	    });
271	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
272	    return s;
273	    });
274	  } catch (e) {
275	    if (e instanceof InsufficientBalanceError) {
276	      return { error: "Insufficient balance. Top up your wallet first." };
277	    }
278	    throw e;
279	  }
280	
281	  await audit(user.id, "server.order", `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`);
282	  // A first paid order can unlock a referral reward (free admin grants don't count).
283	  if (!freeRequested) {
284	    try {
285	      await maybeRewardReferral(user.id);
286	    } catch { /* non-fatal */ }
287	  }
288	  redirect(`/dashboard/servers/${server.id}`);
289	}
