371	// ---------- Wallet (demo top-up until a payment gateway is connected) ----------
372	
373	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
374	  const user = await requireUser();
375	  // Security: never credit a wallet without a real payment. Once Stripe is
376	  // configured, the demo gateway is hard-disabled — top-ups must go through Checkout.
377	  const { stripeConfigured } = await import("./stripe");
378	  if (stripeConfigured()) {
379	    return { error: "Please add funds with a card via the secure checkout." };
380	  }
381	  const amount = Number(formData.get("amount"));
382	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
383	    return { error: "Amount must be between $1 and $1000." };
384	  }
385	  const cents = Math.round(amount * 100);
386	
387	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
388	  // sets. applyCouponToTopup re-validates for this user against the real amount.
389	  const jar = await cookies();
390	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
391	  let bonusCents = 0;
392	  let couponId: string | null = null;
393	  let couponLabel = "";
394	  if (couponCode) {
395	    const result = await applyCouponToTopup(couponCode, cents);
396	    if (result.ok) {
397	      bonusCents = result.bonusCents;
398	      couponId = result.couponId;
399	      couponLabel = result.label;
400	    }
401	  }
402	
403	  await db.$transaction([
404	    db.user.update({
405	      where: { id: user.id },
406	      data: { balanceCents: { increment: cents + bonusCents } },
407	    }),
408	    db.walletTransaction.create({
409	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
410	    }),
411	    ...(bonusCents > 0 && couponId
412	      ? [
413	          db.walletTransaction.create({
414	            data: {
415	              userId: user.id,
416	              amountCents: bonusCents,
417	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
418	            },
419	          }),
420	          db.couponRedemption.create({
421	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
422	          }),
423	          db.coupon.update({
424	            where: { id: couponId },
425	            data: { timesRedeemed: { increment: 1 } },
426	          }),
427	        ]
428	      : []),
429	  ]);
430	  jar.delete(COUPON_COOKIE);
431	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
432	  // First successful paid action may unlock a referral reward for both parties.
433	  try {
434	    await maybeRewardReferral(user.id);
435	  } catch { /* non-fatal */ }
436	  revalidatePath("/dashboard/billing");
437	  return {};
438	}
