499	// ---------- Admin ----------
500	
501	export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
502	  const admin = await requireAdmin();
503	  const serverId = String(formData.get("serverId") ?? "");
504	  const days = Number(formData.get("days"));
505	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
506	    return { error: "Days must be between -365 and 365." };
507	  }
508	  const server = await db.server.findUnique({ where: { id: serverId } });
509	  if (!server) return { error: "Server not found." };
510	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
511	  await db.server.update({
512	    where: { id: serverId },
513	    data: { expiresAt: new Date(base + days * 86400_000) },
514	  });
515	  await audit(admin.id, "admin.extend_server", `${serverId} ${days}d`);
516	  revalidatePath("/admin/subscriptions");
517	  return {};
518	}
