533	export async function adminGrantFreeVps(prev: any, formData: FormData): Promise<{ error?: string }> {
534	  const admin = await requireAdmin();
535	  const parsed = z
536	    .object({
537	      userId: z.string().min(1),
538	      planId: z.string().min(1),
539	      osTemplateId: z.string().min(1),
540	      hostname: z.string().min(3).max(40).regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i),
541	    })
542	    .safeParse({
543	      userId: formData.get("userId"),
544	      planId: formData.get("planId"),
