1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { vpsTermPriceCents, addMonths } from "./billing-terms";
7	
8	/**
9	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
10	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
11	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
12	 * and respects the "one in-flight job per server" invariant.
13	 */
14	
15	/** Allowed scheduled-backup cadences (hours). Kept small + human-friendly. */
16	export const BACKUP_INTERVAL_CHOICES = [12, 24, 48, 72, 168] as const;
17	
18	async function ownedServer(serverId: string) {
19	  const user = await requireUser();
20	  const server = await db.server.findUnique({
21	    where: { id: serverId },
22	    include: { plan: true, osTemplate: true },
23	  });
24	  if (!server) throw new Error("Not found");
25	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
26	  return { user, server };
27	}
28	
29	async function hasInflightJob(serverId: string): Promise<boolean> {
30	  const pending = await db.job.count({
31	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
32	  });
33	  return pending > 0;
34	}
35	
36	// ---------- 1. Scheduled backups ----------
37	
38	/**
39	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
40	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
41	 * first backup on its next pass.
42	 */
43	export async function setBackupSchedule(
44	  serverId: string,
45	  enabled: boolean,
46	  intervalHours: number
47	): Promise<{ error?: string }> {
48	  const { user, server } = await ownedServer(serverId);
49	
50	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
51	    return { error: "Choose a valid backup interval." };
52	  }
53	
54	  await db.server.update({
55	    where: { id: server.id },
56	    data: {
57	      autoBackup: enabled,
58	      backupIntervalHours: enabled ? intervalHours : null,
59	    },
60	  });
61	  await db.auditLog.create({
62	    data: {
63	      userId: user.id,
64	      action: "server.backup_schedule",
65	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
66	    },
67	  });
68	  revalidatePath(`/dashboard/servers/${serverId}`);
69	  return {};
70	}
71	
72	// ---------- 2. Reinstall to a different OS ----------
73	
74	/**
75	 * Switch the server to a different OS image and reinstall. This ERASES all data:
76	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
77	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
78	 */
79	export async function reinstallToOs(
80	  serverId: string,
81	  osTemplateId: string
82	): Promise<{ error?: string }> {
83	  const { user, server } = await ownedServer(serverId);
84	
85	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
86	    return { error: "Server must be running or stopped to reinstall." };
87	  }
88	
89	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
90	  if (!os?.active) return { error: "That operating system isn't available." };
91	  if (os.id === server.osTemplateId) {
92	    return { error: "This server is already running that operating system." };
93	  }
94	  if (server.plan.ramMB < os.minRamMB) {
95	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
96	  }
97	  if (server.plan.diskGB < os.minDiskGB) {
98	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
99	  }
100	
101	  if (await hasInflightJob(serverId)) {
102	    return { error: "Another operation is already in progress on this server." };
103	  }
104	
105	  // Persist the target OS first so the REINSTALL handler (which re-provisions
106	  // from Server.osTemplateId) rebuilds onto the new image, then enqueue.
107	  await db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } });
108	  await db.job.create({ data: { type: "REINSTALL", serverId } });
109	  await db.auditLog.create({
110	    data: {
111	      userId: user.id,
112	      action: "server.reinstall_os",
113	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
114	    },
115	  });
116	  revalidatePath(`/dashboard/servers/${serverId}`);
117	  return {};
118	}
119	
120	// ---------- 3. Resize-down ----------
121	
122	/**
123	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
124	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
125	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
126	 * otherwise). A prorated credit for the price difference over the remaining term
127	 * is returned to the wallet.
128	 */
129	export async function resizeServerDown(
130	  serverId: string,
131	  newPlanId: string
132	): Promise<{ error?: string }> {
133	  const { user, server } = await ownedServer(serverId);
134	
135	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
136	  if (!newPlan?.active) return { error: "Plan not available." };
137	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
138	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
139	
140	  // This action is downgrades only — upgrades go through resizeServer().
141	  if (newPlan.priceCents >= server.plan.priceCents) {
142	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
143	  }
144	  // Disk can't shrink destructively; block the move rather than lose data.
145	  if (newPlan.diskGB < server.plan.diskGB) {
146	    return {
147	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
148	    };
149	  }
150	
151	  if (await hasInflightJob(serverId)) {
152	    return { error: "Another operation is already in progress on this server." };
153	  }
154	
155	  // Prorated credit: refund the price difference for the unused portion of the
156	  // current billing term (paid servers only; free servers get nothing to refund).
157	  let creditCents = 0;
158	  if (!server.isFree && server.expiresAt) {
159	    const now = Date.now();
160	    const periodStart = addMonths(server.expiresAt, -server.termMonths).getTime();
161	    const periodMs = server.expiresAt.getTime() - periodStart;
162	    const remainingFraction =
163	      periodMs > 0
164	        ? Math.max(0, Math.min(1, (server.expiresAt.getTime() - now) / periodMs))
165	        : 0;
166	    const deltaFullTerm =
167	      vpsTermPriceCents(server.plan.priceCents, server.termMonths) -
168	      vpsTermPriceCents(newPlan.priceCents, server.termMonths);
169	    creditCents = Math.max(0, Math.round(deltaFullTerm * remainingFraction));
170	  }
171	
172	  await db.$transaction([
173	    ...(creditCents > 0
174	      ? [
175	          db.user.update({
176	            where: { id: server.userId },
177	            data: { balanceCents: { increment: creditCents } },
178	          }),
179	          db.walletTransaction.create({
180	            data: {
181	              userId: server.userId,
182	              amountCents: creditCents,
183	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
184	            },
185	          }),
186	        ]
187	      : []),
188	    db.job.create({ data: { type: "RESIZE", serverId, payload: { planId: newPlan.id } as any } }),
189	    db.auditLog.create({
190	      data: {
191	        userId: user.id,
192	        action: "server.resize_down",
193	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
194	      },
195	    }),
196	  ]);
197	
198	  revalidatePath(`/dashboard/servers/${serverId}`);
199	  return {};
200	}
