2	//
3	// Plain (non-"use server") module: exports constants and (db-backed) computation
4	// helpers used by the affiliate pages and server actions. Not for client import.
5	//
6	// Accounting model
7	// ----------------
8	// The existing referral engine (lib/actions-growth.ts → maybeRewardReferral)
9	// already credits a referrer's WALLET when a person they referred makes their
10	// first payment, writing a ledger row with the description below. That ledger is
11	// our source of truth for "total affiliate earnings". Payout requests draw
12	// against those earnings and are tracked separately in AffiliatePayout — a payout
13	// is a MANUAL cash-out handled by an admin, it does NOT debit the wallet here.
14	//
15	// available = totalEarned − (PENDING + APPROVED + PAID payouts)   [DECLINED ignored]
16	
17	import { db } from "./db";
18	
19	/** Exact WalletTransaction.description written for the referrer's reward (see
20	 *  lib/actions-growth.ts). Used to total affiliate earnings from the ledger. */
21	export const REFERRAL_EARNING_DESCRIPTION = "Referral bonus — you referred a friend";
22	
23	/** Minimum balance (cents) a customer must have available to request a payout. */
24	export const MIN_PAYOUT_CENTS = 2500; // $25.00
25	
26	/** Payout lifecycle statuses (mirrors AffiliatePayout.status). */
27	export const PAYOUT_STATUSES = ["PENDING", "APPROVED", "PAID", "DECLINED"] as const;
28	export type PayoutStatus = (typeof PAYOUT_STATUSES)[number];
29	
30	/**
31	 * Commission tiers. `perReferralCents` is what the marketing copy advertises a
32	 * paying referral is worth once you reach `minReferrals` paying referrals — an
33	 * escalating incentive. (The wallet credit actually paid per referral is governed
34	 * by the `referral_reward_cents` Setting / REFERRAL_REWARD_CENTS in the growth
35	 * engine; these tiers are the customer-facing program description.)
36	 */
37	export const AFFILIATE_TIERS = [
38	  { name: "Starter", minReferrals: 0, perReferralCents: 500 },
39	  { name: "Pro", minReferrals: 5, perReferralCents: 800 },
40	  { name: "Elite", minReferrals: 15, perReferralCents: 1200 },
41	] as const;
42	
43	export type AffiliateTier = (typeof AFFILIATE_TIERS)[number];
44	
45	/** The tier a customer currently sits in given their paying-referral count. */
46	export function currentTier(payingReferrals: number): AffiliateTier {
47	  let tier: AffiliateTier = AFFILIATE_TIERS[0];
48	  for (const t of AFFILIATE_TIERS) {
49	    if (payingReferrals >= t.minReferrals) tier = t;
50	  }
51	  return tier;
52	}
53	
54	/** The next tier up (null if already at the top), for "N more to unlock…" copy. */
55	export function nextTier(payingReferrals: number): AffiliateTier | null {
56	  return AFFILIATE_TIERS.find((t) => t.minReferrals > payingReferrals) ?? null;
57	}
58	
59	export type AffiliateEarnings = {
60	  referredCount: number;
61	  payingCount: number;
62	  totalEarnedCents: number;
63	  pendingPayoutCents: number; // PENDING + APPROVED (in-flight, not yet cashed out)
64	  paidPayoutCents: number; // PAID
65	  availableCents: number; // totalEarned − (pending + approved + paid)
66	  tier: AffiliateTier;
67	  next: AffiliateTier | null;
68	  canRequestPayout: boolean;
69	};
70	
71	/**
72	 * Compute a customer's affiliate standing: referral counts, lifetime earnings
73	 * (from the wallet ledger) and how much is still available to cash out after
74	 * subtracting non-declined payouts.
75	 */
76	export async function computeAffiliateEarnings(userId: string): Promise<AffiliateEarnings> {
77	  const [referredCount, payingCount, earnedAgg, payouts] = await Promise.all([
78	    db.user.count({ where: { referredById: userId } }),
79	    db.user.count({ where: { referredById: userId, referralRewardedAt: { not: null } } }),
80	    db.walletTransaction.aggregate({
81	      _sum: { amountCents: true },
82	      where: { userId, description: REFERRAL_EARNING_DESCRIPTION },
83	    }),
84	    db.affiliatePayout.findMany({
85	      where: { userId, status: { not: "DECLINED" } },
86	      select: { amountCents: true, status: true },
87	    }),
88	  ]);
89	
90	  const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
91	  let pendingPayoutCents = 0;
92	  let paidPayoutCents = 0;
93	  for (const p of payouts) {
94	    if (p.status === "PAID") paidPayoutCents += p.amountCents;
95	    else pendingPayoutCents += p.amountCents; // PENDING or APPROVED
96	  }
97	
98	  const availableCents = Math.max(0, totalEarnedCents - pendingPayoutCents - paidPayoutCents);
99	
100	  return {
101	    referredCount,
102	    payingCount,
103	    totalEarnedCents,
104	    pendingPayoutCents,
105	    paidPayoutCents,
106	    availableCents,
107	    tier: currentTier(payingCount),
108	    next: nextTier(payingCount),
109	    canRequestPayout: availableCents >= MIN_PAYOUT_CENTS,
110	  };
111	}
