/**
 * Request an affiliate payout for `amountCents`. Guards:
 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
 *  - amount ≤ the caller's currently AVAILABLE affiliate balance (earnings minus
 *    any non-declined payouts). Availability is recomputed server-side inside the
 *    request so a stale client can't over-draw.
 * Creates a PENDING AffiliatePayout. Cash-out itself is manual (admin-processed).
 */
export async function requestAffiliatePayout(
  amountCents: number
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();

  const cents = Math.round(Number(amountCents));
  if (!Number.isFinite(cents) || cents <= 0) {
    return { error: "Enter a valid amount." };
  }
  if (cents < MIN_PAYOUT_CENTS) {
    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
  }

  const earnings = await computeAffiliateEarnings(user.id);
  if (cents > earnings.availableCents) {
    return {
      error: `You only have $${(earnings.availableCents / 100).toFixed(2)} available to withdraw.`,
    };
  }

  await db.affiliatePayout.create({
    data: { userId: user.id, amountCents: cents, status: "PENDING" },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "affiliate.payout_request",
      detail: `$${(cents / 100).toFixed(2)}`,
    },
  });

  revalidatePath("/dashboard/affiliate");
  return { ok: true };
}

