/**
 * Request an affiliate payout for `amountCents`. Model: referral rewards already
 * live in the wallet, so a payout CONVERTS wallet credit into a cash-out request —
 * it DEBITS the wallet now and records a PENDING AffiliatePayout (admin later marks
 * PAID; a DECLINE credits the wallet back). Guards:
 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
 *  - amount ≤ the caller's cashable affiliate balance (unclaimed referral
 *    commission, capped by the actual wallet balance), re-read INSIDE the
 *    transaction so two concurrent requests can't both pass a stale check.
 *  - the wallet debit is an atomic guarded updateMany, so even a race can never
 *    drive the balance negative — the second request fails cleanly.
 */
export async function requestAffiliatePayout(
  amountCents: number
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();

  const cents = Math.round(Number(amountCents));
  if (!Number.isFinite(cents) || cents <= 0) {
    return { error: "Enter a valid amount." };
  }
  if (cents < MIN_PAYOUT_CENTS) {
    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
  }

  try {
    await db.$transaction(async (tx) => {
      // Re-read all state inside the tx to serialize concurrent requests.
      const [account, earnedAgg, payouts] = await Promise.all([
        tx.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } }),
        tx.walletTransaction.aggregate({
          _sum: { amountCents: true },
          where: { userId: user.id, description: REFERRAL_EARNING_DESCRIPTION },
        }),
        tx.affiliatePayout.findMany({
          where: { userId: user.id, status: { not: "DECLINED" } },
          select: { amountCents: true },
        }),
      ]);
      const walletBalanceCents = account?.balanceCents ?? 0;
      const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
      const claimedCents = payouts.reduce((s, p) => s + p.amountCents, 0);
      const availableCents = Math.max(
        0,
        Math.min(walletBalanceCents, totalEarnedCents - claimedCents)
      );
      if (cents > availableCents) throw new PayoutExceedsAvailableError(availableCents);

      // Atomic guarded debit — hard-stops any residual race from overdrawing.
      await debitWallet(tx, user.id, cents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -cents,
          description: "Affiliate payout request (wallet cash-out)",
        },
      });
      await tx.affiliatePayout.create({
        data: { userId: user.id, amountCents: cents, status: "PENDING" },
      });
      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: "affiliate.payout_request",
          detail: `$${(cents / 100).toFixed(2)}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof PayoutExceedsAvailableError) {
      return { error: `You only have $${(e.availableCents / 100).toFixed(2)} available to withdraw.` };
    }
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient wallet balance for this payout." };
    }
    throw e;
  }

  revalidatePath("/dashboard/affiliate");
  return { ok: true };
}

