input.new_string:
/**
 * Move a payout request to APPROVED / PAID / DECLINED. Money already left the
 * wallet when the request was created, so:
 *   - PAID     : just stamp `paidAt` (no wallet change — cash was already reserved).
 *   - DECLINED : credit the reserved amount back to the wallet (cash-out cancelled).
 *   - reactivating a DECLINED payout (back to PENDING/APPROVED/PAID): re-debit it,
 *     guarded, so a declined-then-reinstated payout can't be double-spent.
 * Billing-area gated. The status change + wallet move are one transaction.
 */
export async function adminUpdatePayout(
  id: string,
  status: string
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("billing");

  if (!ALLOWED.includes(status as PayoutStatus)) {
    return { error: "Invalid status." };
  }
  const payout = await db.affiliatePayout.findUnique({ where: { id } });
  if (!payout) return { error: "Payout not found." };

  const wasDeclined = payout.status === "DECLINED";
  const willDecline = status === "DECLINED";

  try {
    await db.$transaction(async (tx) => {
      await tx.affiliatePayout.update({
        where: { id },
        data: {
          status,
          paidAt: status === "PAID" ? new Date() : null,
        },
      });
      if (willDecline && !wasDeclined) {
        // Cancel the cash-out: return the reserved funds to the wallet.
        await tx.user.update({
          where: { id: payout.userId },
          data: { balanceCents: { increment: payout.amountCents } },
        });
        await tx.walletTransaction.create({
          data: {
            userId: payout.userId,
            amountCents: payout.amountCents,
            description: "Affiliate payout declined (funds returned)",
          },
        });
      } else if (!willDecline && wasDeclined) {
        // Reinstating a previously-declined payout: re-reserve the funds (guarded).
        await debitWallet(tx, payout.userId, payout.amountCents);
        await tx.walletTransaction.create({
          data: {
            userId: payout.userId,
            amountCents: -payout.amountCents,
            description: "Affiliate payout reinstated (wallet cash-out)",
          },
        });
      }
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Customer's wallet no longer covers this payout — cannot reinstate." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "affiliate.payout_update",
      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
    },
  });

  revalidatePath("/admin/affiliate");
  return { ok: true };
}

